SELECT * FROM system_heart_beat_record
AND DATE_FORMAT(heart_beat_time, '%Y-%m-%d') >= #{pageForm.startDate}
AND DATE_FORMAT(heart_beat_time, '%Y-%m-%d') <= #{pageForm.endDate}
AND (INSTR(project_path,#{pageForm.keywords}) or INSTR(server_ip,#{pageForm.keywords}) or INSTR(process_no,#{pageForm.keywords}))
order by heart_beat_time desc
